const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
let currentView='home', activeCategory='All', searchTerm='', favorites=new Set(JSON.parse(localStorage.getItem('pv_favorites')||'[]')), playerName=localStorage.getItem('pv_name')||'Player One', playerEmoji=localStorage.getItem('pv_emoji')||'✦', accent=localStorage.getItem('pv_accent')||'#a99aff', roomState=null, socket=null, roomCode='';
const categories=['All','Arcade','Party','Puzzle','Racing','Strategy','Adventure','Simulation','Rhythm','Creative','Survival','Platformer','Sports','Action'];
$('#topName').textContent=playerName;document.documentElement.style.setProperty('--accent',accent);$('#year').textContent=new Date().getFullYear();
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function gameCard(g){return `<article class="game-card"><div class="game-art art-${g.art}"><span class="game-tag">${g.category.toUpperCase()}</span><button class="fav-btn ${favorites.has(g.id)?'is-fav':''}" data-fav="${g.id}" aria-label="Favorite ${g.name}">${favorites.has(g.id)?'♥':'♡'}</button><span class="art-emoji">${g.emoji}</span></div><div class="game-info"><div class="game-title-row"><h3>${g.name}</h3></div><p>${g.desc}</p><div class="game-meta"><span>♧ ${g.players} players</span><button class="play-btn" data-play="${g.id}">Play ↗</button></div></div></article>`}
function bindCards(){ $$('[data-fav]').forEach(b=>b.onclick=()=>{const id=b.dataset.fav;favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('pv_favorites',JSON.stringify([...favorites]));renderCurrent()});$$('[data-play]').forEach(b=>b.onclick=()=>openGame(b.dataset.play));$$('[data-category]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category;currentView='games';renderCurrent()}) }
function visibleGames(){return games.filter(g=>(activeCategory==='All'||g.category===activeCategory)&&(currentView!=='favorites'||favorites.has(g.id))&&(`${g.name} ${g.category} ${g.desc}`.toLowerCase().includes(searchTerm.toLowerCase())))}
function renderFeatured(){ $('#featuredGames').innerHTML=games.slice(0,8).map(gameCard).join('');bindCards() }
function setNav(){ $$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.view===currentView)) }
function renderCurrent(){setNav();if(currentView==='home'){ $('#mainContent').innerHTML=homeMarkup();renderFeatured();wireGlobal();return} if(currentView==='games'||currentView==='favorites'){const list=visibleGames();$('#mainContent').innerHTML=`<div class="view-title"><div class="eyebrow muted">${currentView==='favorites'?'YOUR PERSONAL COLLECTION':'THE PLAYVERSE ARCADE'}</div><h1>${currentView==='favorites'?'Your favorites.':'Find your next obsession.'}</h1><p>${currentView==='favorites'?'All the games you have saved in one place.':'Browse 50+ game worlds. Some are playable prototypes today; more are ideas in the community roadmap.'}</p></div><div class="filter-row">${(currentView==='favorites'?['All']:categories).map(c=>`<button class="filter-chip ${activeCategory===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div><div class="game-grid">${list.map(gameCard).join('')}</div>${list.length?'':`<div class="empty-state"><span>🪐</span><h3>No games found just yet</h3><p>Try another filter, clear your search, or favorite a game from the arcade.</p><button class="btn btn-primary" data-view="games">Explore games</button></div>`}`;$$('[data-filter]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.filter;renderCurrent()});bindCards();wireGlobal();return} if(currentView==='multiplayer'){renderMultiplayer();wireGlobal();return}if(currentView==='community'){renderCommunity();wireGlobal();return}if(currentView==='customize'){renderCustomize();wireGlobal();return}if(currentView==='profile'){renderProfile();wireGlobal();return}}
function homeMarkup(){return `<section class="hero"><div class="hero-orb orb-one"></div><div class="hero-orb orb-two"></div><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> YOUR NEXT FAVORITE GAME IS HERE</div><h1>One universe.<br><span>Endless play.</span></h1><p>Jump into quick matches, build your squad, and find your people. Your next obsession is one click away.</p><div class="hero-buttons"><button class="btn btn-primary" data-view="games">Explore games <span>↗</span></button><button class="btn btn-glass" data-view="multiplayer">♧ Play with friends</button></div><div class="hero-social"><div class="avatar-stack"><i>🦊</i><i>🐸</i><i>🐼</i><i>🐙</i></div><span><b>Good games are better together.</b><br>Invite your people. Make a little chaos.</span></div></div><div class="hero-art"><div class="planet planet-back"></div><div class="planet planet-main"><div class="planet-ring"></div><span>✦</span></div><div class="floating-tag tag-top">✦ <b>PLAY YOUR WAY</b></div><div class="floating-tag tag-bottom"><span class="mini-live"></span> FRIENDS ARE AROUND</div><div class="pixel-star star-a">✦</div><div class="pixel-star star-b">✧</div><div class="pixel-star star-c">✳</div></div><div class="hero-counter"><span>✳</span><div><b>50+ worlds to discover</b><small>And we're just getting started.</small></div><span class="counter-arrow">↗</span></div></section><section class="section-block"><div class="section-heading"><div><div class="eyebrow muted">PICK YOUR VIBE</div><h2>What are we feeling?</h2></div><button class="text-link" data-view="games">All categories ↗</button></div><div class="category-grid"><button class="category-card cat-purple" data-category="Arcade"><span class="category-emoji">👾</span><b>Arcade</b><small>Fast & chaotic</small><span class="category-arrow">↗</span></button><button class="category-card cat-blue" data-category="Party"><span class="category-emoji">🎉</span><b>Party games</b><small>Bring the whole crew</small><span class="category-arrow">↗</span></button><button class="category-card cat-orange" data-category="Puzzle"><span class="category-emoji">🧩</span><b>Puzzle</b><small>Big brain energy</small><span class="category-arrow">↗</span></button><button class="category-card cat-green" data-category="Racing"><span class="category-emoji">🏎️</span><b>Racing</b><small>Speed is the mood</small><span class="category-arrow">↗</span></button><button class="category-card cat-pink" data-category="Strategy"><span class="category-emoji">♟️</span><b>Strategy</b><small>Play it smart</small><span class="category-arrow">↗</span></button></div></section><section class="section-block"><div class="section-heading"><div><div class="eyebrow muted">THE CROWD FAVORITES</div><h2>Games worth your time <span class="heading-spark">✦</span></h2><p class="section-sub">Little games. Big “one more round” energy.</p></div><button class="text-link" data-view="games">See all 50+ ↗</button></div><div class="game-grid" id="featuredGames"></div></section><section class="section-block multiplayer-banner"><div class="mp-copy"><div class="eyebrow">SQUAD UP</div><h2>Your friends called.<br>They want to win.</h2><p>Create a room, share a code, and get up to 50 players together in supported modes.</p><button class="btn btn-primary" data-view="multiplayer">Create a game room ↗</button></div><div class="mp-visual"><div class="mp-ring ring-a"></div><div class="mp-ring ring-b"></div><div class="mp-emoji e1">🐸</div><div class="mp-emoji e2">🐼</div><div class="mp-emoji e3">🦊</div><div class="mp-emoji e4">🐙</div><div class="mp-center">50<span>PLAYERS</span></div><div class="mp-pill">YOUR SQUAD ✦</div></div></section><section class="section-block community-strip"><div class="community-icon">✦</div><div><div class="eyebrow muted">YOU'RE PART OF THE BUILD</div><h2>Got a game idea? We're listening.</h2><p>Tell us what to make, what to fix, and what makes you stay.</p></div><button class="btn btn-secondary" data-view="community">Drop your ideas ↗</button></section><footer class="footer"><a class="brand mini-brand" href="#home"><span class="brand-mark">P</span><span>play<span class="brand-light">verse</span></span></a><span>Made for the love of play. © ${new Date().getFullYear()} PlayVerse</span><div><a href="#community" data-view="community">Feedback</a><a href="#donate" data-open="donate">Support us</a><a href="#settings" data-view="customize">Settings</a></div></footer>`}
function wireGlobal(){ $$('[data-view]').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;activeCategory='All';renderCurrent();window.scrollTo(0,0)});$$('[data-open="donate"]').forEach(b=>b.onclick=()=>openDonate());$('#searchInput').oninput=e=>{searchTerm=e.target.value;if(currentView!=='games'&&currentView!=='favorites')currentView='games';renderCurrent()};$('#profileQuick').onclick=()=>{currentView='profile';renderCurrent()};$('#notifBtn').onclick=()=>toast('You are all caught up. Go play something!');$('#mobileMenu').onclick=()=>{currentView='home';renderCurrent()}}
function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open')}function closeModal(){$('#modalBackdrop').classList.remove('open')}$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus()}});
function openDonate(){openModal(`<div class="eyebrow">KEEP THE UNIVERSE GROWING</div><h2>Fuel the next level. ✦</h2><p>PlayVerse is an indie project. Your support helps cover hosting, game development, and the tools that keep the party going.</p><div class="choice-row" id="donationAmounts"><button class="choice" data-amount="100">₹100</button><button class="choice selected" data-amount="250">₹250</button><button class="choice" data-amount="500">₹500</button><button class="choice" data-amount="1000">₹1,000</button></div><div class="field"><label>YOUR NAME (OPTIONAL)</label><input id="donorName" placeholder="Anonymous legend" maxlength="40"></div><div class="field"><label>A LITTLE MESSAGE (OPTIONAL)</label><input id="donorMessage" placeholder="Keep building cool stuff!" maxlength="120"></div><button class="btn btn-primary block" id="donateSubmit">Continue with ₹250 ↗</button><p class="modal-note">Payment processing is not connected in this starter. Before launch, connect Razorpay or another payment provider and verify payments on the server. This button will not charge you.</p>`);let amount=250;$$('[data-amount]').forEach(b=>b.onclick=()=>{amount=Number(b.dataset.amount);$$('[data-amount]').forEach(x=>x.classList.toggle('selected',x===b));$('#donateSubmit').textContent=`Continue with ₹${amount.toLocaleString('en-IN')} ↗`});$('#donateSubmit').onclick=()=>{const donations=JSON.parse(localStorage.getItem('pv_donation_intents')||'[]');donations.push({amount,name:$('#donorName').value||'Anonymous',message:$('#donorMessage').value||'',at:Date.now()});localStorage.setItem('pv_donation_intents',JSON.stringify(donations));closeModal();toast('Thanks for supporting the idea! Payment setup is still needed.')}}
function openGame(id){const g=games.find(x=>x.id===id);if(!g)return;if(id==='trivia-chaos')return openTrivia(g);if(id==='pixel-pairs')return openMemory(g);if(id==='neon-dash')return openReaction(g);if(id==='cosmic-clicker')return openClicker(g);if(id==='code-cracker')return openCodeCracker(g);if(id==='number-ninja')return openNumberNinja(g);if(id==='word-wizards')return openWordWizards(g);if(id==='bubble-burst')return openBubbleBurst(g);if(id==='goal-glitch')return openGoalGlitch(g);if(id==='maze-mayhem')return openMazeMayhem(g);if(id==='snowball-smash')return openSnowballSmash(g);if(id==='chess-rush')return openChessRush(g);if(id==='paper-planes')return openPaperPlanes(g);if(id==='penguin-pileup')return openPenguinPileup(g);openModal(`<div class="eyebrow">${g.category.toUpperCase()} · GAME PREVIEW</div><h2>${g.name}</h2><p>${g.desc}</p><div class="game-play-area"><div><div class="big-game-emoji">${g.emoji}</div><h3>This world is on the roadmap.</h3><p>It's in the PlayVerse game catalog. The playable prototype is coming as development continues.</p><button class="btn btn-primary" id="voteForGame">Vote to build this game ✦</button></div></div><p class="modal-note">This is a game concept card, not a finished game yet. Use Community Ideas to vote and suggest features.</p>`);$('#voteForGame').onclick=()=>{const votes=JSON.parse(localStorage.getItem('pv_game_votes')||'{}');votes[id]=(votes[id]||0)+1;localStorage.setItem('pv_game_votes',JSON.stringify(votes));closeModal();toast(`Vote saved locally for ${g.name}!`)}}
function openReaction(g){openModal(`<div class="eyebrow">QUICK REFLEXES</div><h2>Neon Dash</h2><p>Wait for green, then click as fast as you can. Don't jump the gun.</p><div class="game-play-area"><div style="width:100%"><div class="score-number" id="reactionScore">—</div><p id="reactionHelp">Press start. Wait for the panel to turn green.</p><button class="reaction-pad" id="reactionPad">START ROUND</button></div></div><p class="modal-note">Single-player prototype · Multiplayer mode can be added through the room server.</p>`);let state='idle',timer,started;const pad=$('#reactionPad');pad.onclick=()=>{if(state==='idle'||state==='done'){state='wait';pad.className='reaction-pad wait';pad.textContent='WAIT FOR GREEN…';$('#reactionHelp').textContent='Do not click yet!';$('#reactionScore').textContent='—';timer=setTimeout(()=>{state='go';started=performance.now();pad.className='reaction-pad ready';pad.textContent='CLICK NOW!'},1200+Math.random()*2600)}else if(state==='wait'){clearTimeout(timer);state='done';pad.className='reaction-pad';pad.textContent='TOO SOON — TRY AGAIN';$('#reactionHelp').textContent='Patience, speedster.'}else if(state==='go'){let ms=Math.round(performance.now()-started);state='done';pad.className='reaction-pad';pad.textContent='PLAY AGAIN';$('#reactionScore').textContent=ms+' ms';$('#reactionHelp').textContent=ms<220?'Ridiculously fast.':ms<320?'Nice reflexes!':'You can shave a few milliseconds off.'}}}
function openClicker(g){openModal(`<div class="eyebrow">IDLE ARCADE</div><h2>Cosmic Clicker</h2><p>Every click adds a star to your tiny universe.</p><div class="game-play-area"><div><div class="big-game-emoji" id="clickerPlanet" style="cursor:pointer">🪐</div><div class="score-number" id="clickerScore">0</div><p>cosmic stars</p><button class="btn btn-primary" id="clickerButton">Collect stardust ✦</button><button class="btn btn-glass" id="clickerReset">Reset</button></div></div>`);let score=0;const bump=()=>{score++;$('#clickerScore').textContent=score;$('#clickerPlanet').style.transform=`rotate(${score*7}deg) scale(${1+Math.min(score%10,8)*.015})`};$('#clickerButton').onclick=bump;$('#clickerPlanet').onclick=bump;$('#clickerReset').onclick=()=>{score=0;$('#clickerScore').textContent='0';$('#clickerPlanet').style.transform='none'}}
function openMemory(g){let emojis=['🍉','🌙','🦊','💎','🍉','🌙','🦊','💎','🐸','🚀','🐸','🚀','🍄','🌈','🍄','🌈'].sort(()=>Math.random()-.5),flipped=[],matched=new Set(),moves=0;openModal(`<div class="eyebrow">MEMORY CHALLENGE</div><h2>Pixel Pairs</h2><p>Find all eight matching pairs. Can you do it in fewer than 20 moves?</p><div class="game-play-area"><div style="width:100%;display:grid;justify-items:center;gap:12px"><div class="memory-grid" id="memoryGrid">${emojis.map((e,i)=>`<button class="memory-cell" data-cell="${i}">?</button>`).join('')}</div><div>Moves: <b id="memoryMoves">0</b> · Pairs: <b id="memoryPairs">0/8</b></div><button class="btn btn-glass" id="memoryReset">Shuffle & restart</button></div></div>`);function reset(){emojis.sort(()=>Math.random()-.5);flipped=[];matched=new Set();moves=0;$('#memoryMoves').textContent='0';$('#memoryPairs').textContent='0/8';$$('[data-cell]').forEach((b,i)=>{b.textContent='?';b.classList.remove('revealed');b.disabled=false})}$$('[data-cell]').forEach(b=>b.onclick=()=>{let i=+b.dataset.cell;if(flipped.includes(i)||matched.has(i)||flipped.length===2)return;b.textContent=emojis[i];b.classList.add('revealed');flipped.push(i);if(flipped.length===2){moves++;$('#memoryMoves').textContent=moves;if(emojis[flipped[0]]===emojis[flipped[1]]){flipped.forEach(j=>matched.add(j));flipped=[];$('#memoryPairs').textContent=`${matched.size/2}/8`;if(matched.size===16)toast(`All pairs in ${moves} moves!`)}else{const old=[...flipped];setTimeout(()=>old.forEach(j=>{const el=$(`[data-cell="${j}"]`);if(el&&!matched.has(j)){el.textContent='?';el.classList.remove('revealed')}}),650);flipped=[]}}});$('#memoryReset').onclick=reset}
function openTrivia(g){const qs=[{q:'Which planet is known as the Red Planet?',a:['Mars','Venus','Jupiter','Mercury'],correct:0},{q:'What does CPU stand for?',a:['Central Processing Unit','Computer Power Utility','Core Program User','Central Pixel Unit'],correct:0},{q:'How many sides does a hexagon have?',a:['Five','Six','Seven','Eight'],correct:1},{q:'Which ocean is the largest?',a:['Atlantic','Indian','Arctic','Pacific'],correct:3},{q:'Which language styles web pages?',a:['HTML','CSS','SQL','Bash'],correct:1}];let i=0,score=0;function show(){const q=qs[i];$('#modalContent').innerHTML=`<div class="eyebrow">TRIVIA CHAOS · ROUND ${i+1}/${qs.length}</div><h2>${q.q}</h2><p>Pick your answer. No overthinking.</p><div class="game-play-area"><div style="width:100%"><div class="trivia-options">${q.a.map((a,j)=>`<button data-answer="${j}">${a}</button>`).join('')}</div><p>Score: <b>${score}</b></p></div></div><p class="modal-note">Solo demo. The multiplayer room service supports lobby chat and action relays; synced trivia rounds need to be wired in next.</p>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{if(+b.dataset.answer===q.correct)score++;i++;if(i<qs.length)show();else $('#modalContent').innerHTML=`<div class="eyebrow">ROUND COMPLETE</div><h2>Nice run! ✦</h2><div class="game-play-area"><div><div class="score-number">${score}/${qs.length}</div><p>${score===qs.length?'Perfect score. Suspiciously good.':score>=3?'Solid trivia energy.':'Rematch? We believe in you.'}</p><button class="btn btn-primary" id="triviaAgain">Play again</button></div></div>`;$('#triviaAgain')?.addEventListener('click',()=>{i=0;score=0;show()})})}show()}
function ensureSocket(){if(!socket){socket=io();socket.on('room:update',r=>{if(roomState&&r.code===roomState.code){roomState=r;updateRoomUI()}});socket.on('room:notice',m=>addChatSystem(m));socket.on('room:chat',m=>addChatMessage(m));socket.on('game:action',p=>{if(p.action==='ping')toast('A player sent a game ping!')})}return socket}
function renderMultiplayer(){ $('#mainContent').innerHTML=`<div class="view-title"><div class="eyebrow muted">PLAY TOGETHER</div><h1>Good games need good company.</h1><p>Create a room, invite your friends with a code, and hang out in the lobby. Rooms allow up to 50 connected players; the current multiplayer starter includes live lobby updates and chat.</p></div><div class="room-layout"><div class="panel"><div class="eyebrow muted">START A NEW PARTY</div><h3>Create your room</h3><p>Choose a game, pick your player name, and we'll make a shareable room code.</p><div class="field"><label>YOUR DISPLAY NAME</label><input id="roomName" maxlength="18" value="${escapeHTML(playerName)}"></div><div class="field"><label>CHOOSE A GAME</label><select id="roomGame"><option>Trivia Chaos</option><option>Shadow Tag</option><option>Kingdom Clash</option><option>Snowball Smash</option><option>Last Lantern</option><option>Penguin Pileup</option><option>Custom Party</option></select></div><button class="btn btn-primary block" id="createRoom">✦ Create multiplayer room</button><div class="divider-text">OR JOIN YOUR FRIENDS</div><div class="field"><label>ROOM CODE</label><input id="joinCode" placeholder="e.g. A7K2P" maxlength="5" style="text-transform:uppercase;letter-spacing:4px"></div><button class="btn btn-secondary block" id="joinRoom">Join a room ↗</button><p class="modal-note">For testing across devices, deploy the server to a public host. A room code only works while the server is running.</p></div><div class="panel" id="roomPanel"><div class="eyebrow muted">YOUR LOBBY</div><h3>Ready when you are.</h3><p>Once you create or join a room, your squad will show up here in real time.</p><div class="empty-state"><span>🪐</span><h3>No room yet</h3><p>Start one, then send the code to your friends.</p></div></div></div>`;$('#createRoom').onclick=()=>{playerName=$('#roomName').value.trim()||'Player One';localStorage.setItem('pv_name',playerName);$('#topName').textContent=playerName;const s=ensureSocket();s.emit('room:create',{name:playerName,game:$('#roomGame').value},res=>{if(!res?.ok)return toast('Could not create room.');roomState=res.room;roomCode=res.room.code;updateRoomUI();toast('Room created! Share the code.')})};$('#joinRoom').onclick=()=>{playerName=$('#roomName').value.trim()||'Player One';const code=$('#joinCode').value.trim().toUpperCase();if(code.length!==5)return toast('Enter the 5-character room code.');ensureSocket().emit('room:join',{name:playerName,code},res=>{if(!res?.ok)return toast(res?.error||'Could not join room.');roomState=res.room;roomCode=res.room.code;updateRoomUI();toast('You joined the room!')})};if(roomState)updateRoomUI()}
function updateRoomUI(){const p=$('#roomPanel');if(!p||!roomState)return;p.innerHTML=`<div class="eyebrow muted">LIVE LOBBY · ${escapeHTML(roomState.game.toUpperCase())}</div><h3>Your room is ready.</h3><div class="room-status"><span>SHARE THIS CODE</span><span>${roomState.players.length}/${roomState.maxPlayers} players</span></div><div class="room-code" id="roomCodeDisplay">${roomState.code}</div><button class="btn btn-secondary block" id="copyRoom">Copy invite code ↗</button><div class="room-status"><span>PLAYERS IN LOBBY</span><span class="live-dot"></span></div><div class="player-list">${roomState.players.map((p,i)=>`<div class="player-row"><span class="player-dot" style="color:${p.color}">${i===0?'♛':'✦'}</span><span>${escapeHTML(p.name)} ${i===0?'<small>(host)</small>':''}</span></div>`).join('')}</div><h3 style="margin-top:20px">Lobby chat</h3><div class="chat-box" id="chatBox"><div class="chat-message">Welcome to the lobby. Be kind, have fun.</div></div><form class="chat-form" id="chatForm"><input id="chatInput" placeholder="Say something nice..." maxlength="240"><button class="btn btn-primary">Send</button></form><div style="display:flex;gap:8px;margin-top:12px"><button class="btn btn-glass" id="pingRoom">Send game ping</button><button class="btn btn-glass" id="leaveRoom">Leave room</button></div><p class="modal-note">Room cap is 50. Actual game-state syncing, moderation, persistence and production scaling are additional launch steps.</p>`;$('#copyRoom').onclick=async()=>{try{await navigator.clipboard.writeText(roomState.code);toast('Room code copied!')}catch(e){toast('Your room code is '+roomState.code)}};$('#chatForm').onsubmit=e=>{e.preventDefault();const message=$('#chatInput').value.trim();if(message){socket.emit('room:chat',{message});$('#chatInput').value=''}};$('#pingRoom').onclick=()=>socket.emit('game:action',{action:'ping',data:{at:Date.now()}});$('#leaveRoom').onclick=()=>{socket.emit('room:leave');roomState=null;renderMultiplayer();toast('You left the room.')}}
function addChatMessage(m){const box=$('#chatBox');if(!box)return;const el=document.createElement('div');el.className='chat-message';const b=document.createElement('b');b.textContent=m.name+': ';el.append(b,document.createTextNode(m.message));box.append(el);box.scrollTop=box.scrollHeight}
function addChatSystem(m){const box=$('#chatBox');if(!box)return;const el=document.createElement('div');el.className='chat-message';el.style.color='#7fd9bd';el.textContent='✦ '+m;box.append(el);box.scrollTop=box.scrollHeight}
function renderCommunity(){const ideas=JSON.parse(localStorage.getItem('pv_ideas')||'[]');const votes=JSON.parse(localStorage.getItem('pv_idea_votes')||'{}');$('#mainContent').innerHTML=`<div class="view-title"><div class="eyebrow muted">COMMUNITY LAB</div><h1>Help build the next obsession.</h1><p>Tell us what game should exist, which feature deserves love, and what we should fix. In this starter, submissions and votes are saved in this browser; a shared database is needed for a public community.</p></div><div class="room-layout"><div class="panel"><div class="eyebrow muted">DROP AN IDEA</div><h3>Your opinion actually matters here.</h3><form id="ideaForm"><div class="field"><label>WHAT IS THIS ABOUT?</label><select id="ideaType"><option>New game idea</option><option>Feature request</option><option>Something I love</option><option>Something to improve</option><option>Bug report</option></select></div><div class="field"><label>SHORT TITLE</label><input id="ideaTitle" placeholder="e.g. Add custom profile banners" maxlength="70" required></div><div class="field"><label>TELL US MORE</label><textarea id="ideaDesc" placeholder="What would make PlayVerse more fun for you?" maxlength="700" required></textarea></div><div class="field"><label>YOUR NAME (OPTIONAL)</label><input id="ideaAuthor" placeholder="Anonymous player" maxlength="30"></div><button class="btn btn-primary block">Send idea ✦</button></form></div><div class="panel"><div class="eyebrow muted">THE COMMUNITY BOARD</div><h3>Ideas from players</h3><p>Vote for ideas you would love to see.</p><div class="ideas-list">${ideas.length?ideas.map((it,i)=>`<div class="idea-card"><button class="idea-votes" data-vote="${it.id}">↑<span>${(it.votes||0)+(votes[it.id]||0)}</span></button><div><span class="pill-label">${escapeHTML(it.type)}</span><h4>${escapeHTML(it.title)}</h4><p>${escapeHTML(it.desc)}</p><small>by ${escapeHTML(it.author||'Anonymous')} · ${new Date(it.at).toLocaleDateString()}</small></div></div>`).join(''):`<div class="empty-state"><span>💡</span><h3>It's a blank canvas.</h3><p>Be the first to drop an idea. The best worlds start somewhere.</p></div>`}</div></div></div>`;$('#ideaForm').onsubmit=e=>{e.preventDefault();const arr=JSON.parse(localStorage.getItem('pv_ideas')||'[]');arr.unshift({id:'i'+Date.now(),type:$('#ideaType').value,title:$('#ideaTitle').value.trim(),desc:$('#ideaDesc').value.trim(),author:$('#ideaAuthor').value.trim()||'Anonymous',at:Date.now(),votes:0});localStorage.setItem('pv_ideas',JSON.stringify(arr));renderCommunity();toast('Idea saved in this browser. Thank you!')};$$('[data-vote]').forEach(b=>b.onclick=()=>{const id=b.dataset.vote,v=JSON.parse(localStorage.getItem('pv_idea_votes')||'{}');if(v[id]){toast('You already voted for this idea on this browser.');return}v[id]=1;localStorage.setItem('pv_idea_votes',JSON.stringify(v));const arr=JSON.parse(localStorage.getItem('pv_ideas')||'[]');const it=arr.find(x=>x.id===id);if(it)it.votes=(it.votes||0)+1;localStorage.setItem('pv_ideas',JSON.stringify(arr));renderCommunity();toast('Vote added!')})}
function renderCustomize(){$('#mainContent').innerHTML=`<div class="view-title"><div class="eyebrow muted">MAKE IT YOURS</div><h1>Your universe, your rules.</h1><p>Personalize your profile, choose your vibe, and set your own PlayVerse style.</p></div><div class="room-layout"><div class="panel"><div class="eyebrow muted">PROFILE LOOK</div><h3>Choose your avatar</h3><div class="choice-row" id="avatarChoices">${['✦','🦊','🐸','🐼','🐙','👾','🦄','🤖','🐲','🌙','🔥','🎮'].map(e=>`<button class="choice ${playerEmoji===e?'selected':''}" data-emoji="${e}" style="font-size:20px">${e}</button>`).join('')}</div><div class="field"><label>DISPLAY NAME</label><input id="customName" maxlength="18" value="${escapeHTML(playerName)}"></div><div class="field"><label>ACCENT COLOR</label><div class="theme-options">${['#a99aff','#64e5ff','#ff9ec8','#ffb86b','#8ce6b5','#f3dc77','#f08a8a'].map(c=>`<button class="theme-swatch ${accent===c?'active':''}" data-accent="${c}" style="background:${c}" aria-label="${c}"></button>`).join('')}</div></div><button class="btn btn-primary" id="saveCustomize">Save my style ↗</button></div><div class="panel"><div class="eyebrow muted">LIVE PREVIEW</div><h3>Looking good already.</h3><div class="profile-hero" style="margin-top:18px"><div class="profile-big" id="previewAvatar">${playerEmoji}</div><div><h2 id="previewName">${escapeHTML(playerName)}</h2><p>✦ PlayVerse explorer · Level 1</p></div></div><p>Your chosen accent updates your interface and profile preview. More unlockable themes, avatar items and cosmetics can be added later.</p><div class="field"><label>ACCESSIBILITY & PREFERENCES</label><label style="display:flex;gap:9px;align-items:center;font-weight:400"><input type="checkbox" id="reduceMotion" ${localStorage.getItem('pv_reduce_motion')==='true'?'checked':''}> Reduce motion effects</label><label style="display:flex;gap:9px;align-items:center;font-weight:400;margin-top:10px"><input type="checkbox" id="quietSounds" ${localStorage.getItem('pv_quiet_sounds')==='true'?'checked':''}> Mute game sounds (future games)</label></div></div></div>`;$$('[data-emoji]').forEach(b=>b.onclick=()=>{playerEmoji=b.dataset.emoji;$$('[data-emoji]').forEach(x=>x.classList.toggle('selected',x===b));$('#previewAvatar').textContent=playerEmoji});$$('[data-accent]').forEach(b=>b.onclick=()=>{accent=b.dataset.accent;$$('[data-accent]').forEach(x=>x.classList.toggle('active',x===b));$('#previewAvatar').style.background=accent});$('#customName').oninput=e=>$('#previewName').textContent=e.target.value||'Player One';$('#saveCustomize').onclick=()=>{playerName=$('#customName').value.trim()||'Player One';localStorage.setItem('pv_name',playerName);localStorage.setItem('pv_emoji',playerEmoji);localStorage.setItem('pv_accent',accent);localStorage.setItem('pv_reduce_motion',$('#reduceMotion').checked);localStorage.setItem('pv_quiet_sounds',$('#quietSounds').checked);document.documentElement.style.setProperty('--accent',accent);$('#topName').textContent=playerName;toast('Your PlayVerse style is saved!')}}
function renderProfile(){$('#mainContent').innerHTML=`<div class="view-title"><div class="eyebrow muted">PLAYER CARD</div><h1>Your little corner of the universe.</h1><p>Your PlayVerse identity, saved favorites, and player stats.</p></div><div class="profile-hero"><div class="profile-big" style="background:${accent}">${playerEmoji}</div><div><h2>${escapeHTML(playerName)}</h2><p>✦ PlayVerse explorer · Joined today-ish</p><button class="btn btn-secondary" style="margin-top:12px" data-view="customize">Customize profile ↗</button></div></div><div class="stat-grid"><div class="stat-card"><b>${favorites.size}</b><span>Saved favorites</span></div><div class="stat-card"><b>${JSON.parse(localStorage.getItem('pv_ideas')||'[]').length}</b><span>Ideas submitted here</span></div><div class="stat-card"><b>${JSON.parse(localStorage.getItem('pv_game_votes')||'{}')?Object.keys(JSON.parse(localStorage.getItem('pv_game_votes')||'{}')).length:0}</b><span>Game concepts voted on</span></div></div><section class="section-block"><div class="section-heading"><div><div class="eyebrow muted">YOUR COLLECTION</div><h2>Saved games</h2></div><button class="text-link" data-view="favorites">View favorites ↗</button></div><div class="game-grid">${games.filter(g=>favorites.has(g.id)).slice(0,4).map(gameCard).join('')||'<div class="empty-state" style="grid-column:1/-1"><span>♡</span><h3>Your favorites live here.</h3><p>Save games from the arcade to build your collection.</p></div>'}</div></section>`;bindCards()}
// Home markup is authored once; first render attaches working controls.
renderFeatured();wireGlobal();


// Additional fully playable browser games. These are client-side prototypes; online
// synchronized gameplay is separate from the lobby/chat service.
function gameShell(g,tag,content,sub='Playable browser game · Scores are stored on this device.'){
 openModal(`<div class="eyebrow">${tag} · PLAYVERSE ARCADE</div><h2>${g.name}</h2><p>${g.desc}</p><div class="game-play-area"><div style="width:100%">${content}</div></div><p class="modal-note">${sub}</p>`);
}
function openCodeCracker(g){let secret=[],tries=0;const start=()=>{secret=Array.from({length:4},()=>Math.floor(Math.random()*6)+1);tries=0;render()};function render(msg=''){gameShell(g,'LOGIC PUZZLE',`<p>Crack the 4-digit code. Each digit is 1–6. Green = right digit and place; yellow = right digit, wrong place.</p><div class="field"><label>YOUR GUESS</label><input id="codeGuess" inputmode="numeric" maxlength="4" placeholder="e.g. 1352"></div><button class="btn btn-primary" id="codeTry">Check code</button><button class="btn btn-glass" id="codeNew">New code</button><p id="codeMsg">${msg||'You have unlimited guesses. Think carefully!'}</p><div id="codeHistory" style="display:grid;gap:7px;margin-top:12px"></div>`);$('#codeTry').onclick=()=>{const val=$('#codeGuess').value.trim();if(!/^[1-6]{4}$/.test(val))return $('#codeMsg').textContent='Enter exactly four digits from 1 to 6.';tries++;const a=val.split('').map(Number),exact=a.filter((n,i)=>n===secret[i]).length;let overlap=0;const x={},y={};a.forEach((n,i)=>{if(n!==secret[i])x[n]=(x[n]||0)+1});secret.forEach((n,i)=>{if(n!==a[i])y[n]=(y[n]||0)+1});Object.keys(x).forEach(k=>overlap+=Math.min(x[k],y[k]||0));const row=document.createElement('div');row.className='panel';row.style.padding='10px';row.textContent=`${val} — 🟢 ${exact} exact · 🟡 ${overlap} misplaced`;$('#codeHistory').prepend(row);$('#codeGuess').value='';$('#codeMsg').textContent=exact===4?`Unlocked in ${tries} guesses! 🎉`:`Guess ${tries} logged. Keep cracking.`;if(exact===4)$('#codeTry').disabled=true};$('#codeNew').onclick=start}start()}
function openNumberNinja(g){let score=0,round=0,answer=0;const next=()=>{round++;let a,b;const op=['+','−','×'][Math.floor(Math.random()*3)];if(op==='+'){a=rand(5,70);b=rand(3,40);answer=a+b}else if(op==='−'){a=rand(15,99);b=rand(2,a);answer=a-b}else{a=rand(2,12);b=rand(2,12);answer=a*b}gameShell(g,'MATH SPRINT',`<div class="score-number">${score} pts</div><p>Question ${round} · Solve before you peek at a calculator.</p><h2 style="text-align:center;font-size:36px">${a} ${op} ${b} = ?</h2><form id="mathForm"><input id="mathAnswer" type="number" placeholder="Your answer" required style="margin:12px 0"><button class="btn btn-primary block">Lock answer</button></form><p id="mathFeedback"></p><button class="btn btn-glass" id="mathNext">Next question</button>`);$('#mathForm').onsubmit=e=>{e.preventDefault();const val=Number($('#mathAnswer').value);$('#mathFeedback').textContent=val===answer?'Correct! +1 point ✦':`Not quite — the answer was ${answer}.`;if(val===answer)score++;$('#mathNext').textContent='Next challenge →';$('#mathForm').querySelector('button').disabled=true};$('#mathNext').onclick=next};next()}
function rand(min,max){return Math.floor(Math.random()*(max-min+1))+min}
function openWordWizards(g){const words=['GALAXY','PUZZLE','ROCKET','DRAGON','GAMING','PLANET','WIZARD','JUNGLE','PIXELS','CASTLE','ORBITAL','NEBULA'];let score=0,word='';function next(){word=words[rand(0,words.length-1)];const scramble=word.split('').sort(()=>Math.random()-.5).join('');gameShell(g,'WORD MAGIC',`<div class="score-number">${score} pts</div><p>Unscramble the letters to reveal the hidden word.</p><div class="score-number" style="letter-spacing:8px">${scramble}</div><form id="wordForm"><input id="wordAnswer" placeholder="Type the word" autocomplete="off" required><button class="btn btn-primary block" style="margin-top:10px">Cast spell</button></form><p id="wordFeedback"></p><button class="btn btn-glass" id="wordNext">Skip / next word</button>`);$('#wordForm').onsubmit=e=>{e.preventDefault();const ok=$('#wordAnswer').value.trim().toUpperCase()===word;$('#wordFeedback').textContent=ok?'Correct spell! +1 point ✨':`Not this time. The word was ${word}.`;if(ok)score++;$('#wordForm').querySelector('button').disabled=true};$('#wordNext').onclick=next}next()}
function openBubbleBurst(g){let score=0,time=20,timer=null,ended=false;function draw(){gameShell(g,'20-SECOND ARCADE',`<div style="display:flex;justify-content:space-between"><b>Score: <span id="bubbleScore">${score}</span></b><b>Time: <span id="bubbleTime">${time}</span>s</b></div><p>Pop as many bubbles as you can before time runs out!</p><div id="bubbleField" style="min-height:230px;display:grid;grid-template-columns:repeat(4,1fr);gap:9px;align-items:center">${Array.from({length:16},(_,i)=>`<button data-bubble="${i}" style="font-size:27px;min-height:48px;border:1px solid #ffffff20;border-radius:14px;background:#a99aff18;cursor:pointer">${Math.random()>.45?'🫧':'·'}</button>`).join('')}</div><button class="btn btn-secondary" id="bubbleRestart">Start / restart</button><p id="bubbleEnd"></p>`);$$('[data-bubble]').forEach(b=>b.onclick=()=>{if(ended)return;score+=b.textContent==='🫧'?2:1;$('#bubbleScore').textContent=score;b.textContent=['🫧','💥','✨','🫧','·'][rand(0,4)]});$('#bubbleRestart').onclick=()=>{clearInterval(timer);score=0;time=20;ended=false;$('#bubbleScore').textContent=score;$('#bubbleTime').textContent=time;$('#bubbleEnd').textContent='Go go go!';timer=setInterval(()=>{time--;$('#bubbleTime').textContent=time;if(time<=0){clearInterval(timer);ended=true;$('#bubbleEnd').textContent=`Time! Final score: ${score}`}},1000)}}draw()}
function openGoalGlitch(g){let score=0,shots=5;function shoot(){gameShell(g,'PENALTY SHOOTOUT',`<div class="score-number">${score} / ${5-shots}</div><p>Choose where to shoot. The keeper will guess a side.</p><div style="display:flex;justify-content:center;gap:12px;font-size:50px;margin:20px">🥅</div><div class="choice-row" style="justify-content:center"><button class="choice" data-shot="Left">⬅ Left</button><button class="choice" data-shot="Center">⬆ Center</button><button class="choice" data-shot="Right">Right ➡</button></div><p id="shotFeedback">${shots} shots remaining</p><button class="btn btn-primary" id="shotAgain">${shots?'Take shot':'Play again'}</button>`);$$('[data-shot]').forEach(b=>b.onclick=()=>{if(shots<=0)return;const keeper=['Left','Center','Right'][rand(0,2)];const goal=b.dataset.shot!==keeper;shots--;if(goal)score++;$('#shotFeedback').textContent=goal?`GOOOAL! Keeper dived ${keeper.toLowerCase()}.`:`Saved! Keeper guessed ${keeper.toLowerCase()}.`;$$('[data-shot]').forEach(x=>x.disabled=true);$('#shotAgain').textContent=shots?'Next shot':'Final score: '+score+'/5';$('#shotAgain').onclick=()=>{if(shots<=0){score=0;shots=5}shoot()}})}shoot()}
function openMazeMayhem(g){const n=7;let pos=0,moves=0;const walls=new Set([2,4,9,11,16,18,23,25,30,32,37,39,44]);walls.delete(9);walls.delete(16);walls.delete(23);walls.delete(30);walls.delete(37);function render(){gameShell(g,'MAZE RUNNER',`<p>Reach the glowing exit. Use arrow keys or the controls. Watch the walls!</p><div id="mazeGrid" style="display:grid;grid-template-columns:repeat(7,minmax(25px,42px));gap:4px;justify-content:center">${Array.from({length:49},(_,i)=>`<div style="height:38px;border-radius:7px;display:grid;place-items:center;background:${walls.has(i)?'#24223b':i===48?'#2e6d5b':'#a99aff14'};border:1px solid #ffffff12">${i===pos?'🧙':i===48?'🚪':walls.has(i)?'':' '}</div>`).join('')}</div><p style="text-align:center">Moves: ${moves}</p><div style="display:grid;grid-template-columns:repeat(3,52px);gap:5px;justify-content:center"><span></span><button class="choice" data-dir="up">↑</button><span></span><button class="choice" data-dir="left">←</button><button class="choice" data-dir="down">↓</button><button class="choice" data-dir="right">→</button></div><p id="mazeMsg" style="text-align:center"></p><button class="btn btn-glass" id="mazeReset">Restart maze</button>`);function move(d){let r=Math.floor(pos/7),c=pos%7;if(d==='up')r--;if(d==='down')r++;if(d==='left')c--;if(d==='right')c++;if(r<0||r>=7||c<0||c>=7)return;const np=r*7+c;if(walls.has(np))return;pos=np;moves++;render();if(pos===48)$('#mazeMsg').textContent=`Escaped in ${moves} moves! ✨`}$$('[data-dir]').forEach(b=>b.onclick=()=>move(b.dataset.dir));$('#mazeReset').onclick=()=>{pos=0;moves=0;render()};window._mazeKey=e=>{if($('#mazeGrid')){const map={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};if(map[e.key]){e.preventDefault();move(map[e.key])}}}}render();document.addEventListener('keydown',window._mazeKey)}
function openSnowballSmash(g){let wins=0,round=0;const options=['🪨 Rock','📄 Paper','✂️ Scissors'];function draw(msg='Choose your move!'){gameShell(g,'ROCK PAPER SCISSORS',`<div class="score-number">${wins} wins</div><p>Round ${round+1} · First, choose your weapon.</p><div class="choice-row" style="justify-content:center">${options.map((x,i)=>`<button class="choice" data-rps="${i}" style="font-size:15px">${x}</button>`).join('')}</div><p id="rpsFeedback">${msg}</p><button class="btn btn-glass" id="rpsReset">Reset score</button>`);$$('[data-rps]').forEach(b=>b.onclick=()=>{const you=+b.dataset.rps,bot=rand(0,2);round++;const result=you===bot?'Draw!':(you-bot+3)%3===1?'You win this round!':'CPU wins this round.';if(result.startsWith('You win'))wins++;$('#rpsFeedback').textContent=`You: ${options[you]} · CPU: ${options[bot]}. ${result}`;$$('[data-rps]').forEach(x=>x.disabled=true);$('#rpsReset').onclick=()=>{wins=0;round=0;draw()}});$('#rpsReset').onclick=()=>{wins=0;round=0;draw()}}draw()}
function openChessRush(g){let board=Array(9).fill(''),turn='X',done=false;function draw(msg='You are X. Tap a square.'){gameShell(g,'TIC-TAC-TOE DUEL',`<p>Play against a simple CPU opponent. Get three in a row.</p><div id="tttBoard" style="display:grid;grid-template-columns:repeat(3,78px);gap:7px;justify-content:center">${board.map((v,i)=>`<button data-ttt="${i}" class="choice" style="height:78px;font-size:32px">${v||'·'}</button>`).join('')}</div><p id="tttMsg" style="text-align:center">${msg}</p><button class="btn btn-primary" id="tttReset">New match</button>`);$$('[data-ttt]').forEach(b=>b.onclick=()=>{const i=+b.dataset.ttt;if(done||board[i])return;board[i]='X';let w=winner();if(w){done=true;return draw(w==='X'?'You win! 🏆':'Draw match!')};const free=board.map((v,j)=>v?null:j).filter(v=>v!==null);if(free.length){board[free[rand(0,free.length-1)]]='O';w=winner();if(w)done=true}draw(w==='O'?'CPU wins this round.':free.length?'CPU played. Your move.':'Draw match!')});$('#tttReset').onclick=()=>{board=Array(9).fill('');done=false;draw()}}function winner(){for(const [a,b,c] of [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]])if(board[a]&&board[a]===board[b]&&board[b]===board[c])return board[a];return board.every(Boolean)?'D':null}draw()}
function openPaperPlanes(g){let distance=0,attempt=0;function draw(msg='Set your angle and power, then launch!'){gameShell(g,'PAPER PLANE FLIGHT',`<div class="score-number">Best: ${Math.max(distance,Number(localStorage.getItem('pv_plane_best')||0))} m</div><p>Angle and power change your flight distance. Wind is random each throw.</p><div class="field"><label>LAUNCH ANGLE: <span id="angleLabel">35</span>°</label><input id="planeAngle" type="range" min="10" max="80" value="35"></div><div class="field"><label>POWER: <span id="powerLabel">75</span>%</label><input id="planePower" type="range" min="20" max="100" value="75"></div><button class="btn btn-primary block" id="planeLaunch">Launch plane 🛩️</button><p id="planeResult">${msg}</p><button class="btn btn-glass" id="planeAgain">Reset attempts</button>`);$('#planeAngle').oninput=e=>$('#angleLabel').textContent=e.target.value;$('#planePower').oninput=e=>$('#powerLabel').textContent=e.target.value;$('#planeLaunch').onclick=()=>{const a=Number($('#planeAngle').value)*Math.PI/180,p=Number($('#planePower').value)/100,wind=rand(-8,8);distance=Math.max(1,Math.round((Math.sin(2*a)*p*100)+wind));attempt++;const best=Math.max(distance,Number(localStorage.getItem('pv_plane_best')||0));localStorage.setItem('pv_plane_best',best);$('#planeResult').textContent=`Flight #${attempt}: ${distance} metres! Wind ${wind>=0?'+':''}${wind}. ${distance>=85?'World-class glide!':'Tweak the angle and try again.'}`};$('#planeAgain').onclick=()=>{attempt=0;distance=0;draw('Fresh runway!') }}draw()}
function openPenguinPileup(g){let score=0,seconds=15,timer=null,started=false;function draw(){gameShell(g,'WOBBLE SURVIVAL',`<div class="score-number"><span id="penguinScore">${score}</span> points</div><p>Tap the penguin before it escapes. Every tap moves it to a new spot. How many can you catch in 15 seconds?</p><div id="penguinArena" style="height:210px;position:relative;border-radius:18px;background:#a99aff13;border:1px solid #ffffff1c"><button id="penguinTarget" style="position:absolute;left:42%;top:40%;font-size:40px;border:0;background:transparent;cursor:pointer">🐧</button></div><p>Time left: <b id="penguinTime">${seconds}</b>s</p><button class="btn btn-primary" id="penguinStart">${started?'Restart':'Start game'}</button>`);$('#penguinStart').onclick=()=>{clearInterval(timer);score=0;seconds=15;started=true;$('#penguinScore').textContent='0';$('#penguinTime').textContent='15';$('#penguinTarget').disabled=false;$('#penguinTarget').onclick=()=>{score++;$('#penguinScore').textContent=score;$('#penguinTarget').style.left=rand(2,78)+'%';$('#penguinTarget').style.top=rand(2,72)+'%';$('#penguinTarget').style.transform=`rotate(${rand(-35,35)}deg)`};timer=setInterval(()=>{seconds--;$('#penguinTime').textContent=seconds;if(seconds<=0){clearInterval(timer);$('#penguinTarget').disabled=true;$('#penguinStart').textContent='Play again';toast(`Penguin Pileup: ${score} catches!`) }},1000)}}draw()}
